package vn.edu.eaut.lab9.repository; import jakarta.persistence.*;import vn.edu.eaut.lab9.config.JPAUtil;import vn.edu.eaut.lab9.model.*;import java.util.*; public class DiemRepository extends BaseRepository<Diem,Integer>{protected Class<Diem> type(){return Diem.class;} public List<Diem> findAll(){EntityManager e=JPAUtil.getEntityManagerFactory().createEntityManager();try{return e.createQuery("select d from Diem d join fetch d.sinhVien join fetch d.monHoc order by d.id desc",Diem.class).getResultList();}finally{e.close();}} public void saveWithStudentAndDefaultGrade(SinhVien sv, MonHoc mh){tx(e->{e.persist(sv);e.persist(new Diem(sv,mh,0,0,0));});}}
